/// Each fixture in `payload.invalid-examples.json` MUST be
/// rejected by at least one of: serde deserialization, or
/// JSON-Schema validation under the `validate` feature. The
/// fixture file documents the producer-side bug class that
/// each payload exemplifies; this generated test pins it.
#[cfg(feature = "validate")]
#[test]
fn rejects_invalid_examples() {
    use trust_tasks_rs::validate::ValidatedPayload;
    let fixtures: &[(&str, &str)] = &[
        (
            "The relationship credential is named by vault handle, never carried: a request that ships the credential itself is rejected, because the VTA presents only what its vault holds.",
            "{\n  \"counterpartyDid\": \"did:key:z6MkrBobForAliceRelationshipKey444444444444444\",\n  \"relationshipCredential\": {\n    \"type\": [\n      \"VerifiableCredential\",\n      \"RelationshipCredential\"\n    ]\n  },\n  \"relationshipDid\": \"did:key:z6MkrAliceForBobRelationshipKey333333333333333\",\n  \"relationshipThreadId\": \"urn:uuid:9e8d7c6b-0000-4000-8000-000000000a01\",\n  \"witness\": \"did:webvh:QmWitness:witness.example.org:a\"\n}",
        ),
        (
            "relationshipThreadId is required: witness/session obliges the producer to set parentThreadId on every document of the session.",
            "{\n  \"counterpartyDid\": \"did:key:z6MkrBobForAliceRelationshipKey444444444444444\",\n  \"relationshipCredentialId\": \"vrc-alice-to-bob\",\n  \"relationshipDid\": \"did:key:z6MkrAliceForBobRelationshipKey333333333333333\",\n  \"witness\": \"did:webvh:QmWitness:witness.example.org:a\"\n}",
        ),
        (
            "The witness is named by DID; a URL is not a party the VTA can resolve transports for or check the VWC's issuer against.",
            "{\n  \"counterpartyDid\": \"did:key:z6MkrBobForAliceRelationshipKey444444444444444\",\n  \"relationshipCredentialId\": \"vrc-alice-to-bob\",\n  \"relationshipDid\": \"did:key:z6MkrAliceForBobRelationshipKey333333333333333\",\n  \"relationshipThreadId\": \"urn:uuid:9e8d7c6b-0000-4000-8000-000000000a01\",\n  \"witness\": \"https://witness.example.org/a\"\n}",
        ),
        (
            "A member presentation is never supplied by the caller: membership names a vault handle and, optionally, the member DID, and the VTA builds the presentation itself.",
            "{\n  \"counterpartyDid\": \"did:key:z6MkrBobForAliceRelationshipKey444444444444444\",\n  \"membership\": {\n    \"credentialId\": \"vmc-community-example\",\n    \"memberPresentation\": {}\n  },\n  \"relationshipCredentialId\": \"vrc-alice-to-bob\",\n  \"relationshipDid\": \"did:key:z6MkrAliceForBobRelationshipKey333333333333333\",\n  \"relationshipThreadId\": \"urn:uuid:9e8d7c6b-0000-4000-8000-000000000a01\",\n  \"witness\": \"did:webvh:QmWitness:witness.example.org:a\"\n}",
        ),
    ];
    for (i, (note, raw)) in fixtures.iter().enumerate() {
        let value: serde_json::Value = match serde_json::from_str(raw) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let serde_ok = serde_json::from_value::<spec::Payload>(value.clone()).is_ok();
        let schema_ok = spec::Payload::validate_value(&value).is_ok();
        assert!(
            !(serde_ok && schema_ok),
            "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
            i + 1,
            note,
            raw
        );
    }
}
